<?php declare(strict_types=1); namespace Core\Console\Commands; use Core\Console\Command; use Core\Database\DatabaseManager; use Core\Database\Migration\Migrator; use Core\Database\Schema\SchemaBuilder; final class MigrateCommand extends Command { protected string $name = 'migrate'; protected string $description = 'Run pending database migrations (use --fresh to drop all tables first).'; public function handle(array $args, array $options): int { $connection = $this->app->get(DatabaseManager::class)->connection(); $migrator = new Migrator( $connection, new SchemaBuilder($connection), $this->app->basePath('database/migrations'), ); if ($this->option($options, 'fresh') === true) { $this->info('Dropping all tables...'); $executed = $migrator->fresh(); } else { $executed = $migrator->migrate(); } if ($executed === []) { $this->line('Nothing to migrate.'); return 0; } foreach ($executed as $migration) { $this->success('Migrated: ' . $migration); } return 0; } } 